public boolean hasMetaDataLines()
{
    return (select firstonly RecId from AVADAIReportExportLine
        where AVADAIReportExportLine.ExportId == this.ExportId).RecId != 0;
}

public static AVADAIReportExportTable find(
    AVADAIExecutionId _executionId,
    boolean _forUpdate = false,
    UserConnection _userConnection = null)
{
    AVADAIReportExportTable export;

    if (_executionId)
    {
        export.selectForUpdate(_forUpdate);
        if (_userConnection)
        {
            export.setConnection(_userConnection);
        }

        select firstonly export
            where export.ExecutionId ==_executionId;
    }

    return export;

}

public static AVADAIReportExportTable findAckFileName(
    AVADAIServerId _serverId,
    AVADAIFileNameAck _fileNameAck, 
    boolean _forUpdate = false,
    UserConnection _userConnection = null)
{
    AVADAIReportExportTable export;

    if (_serverId && _fileNameAck)
    {
        export.selectForUpdate(_forUpdate);
        if (_userConnection)
        {
            export.setConnection(_userConnection);
        }

        select firstonly export
            where export.ServerId ==_serverId
                && export.AckFileName == _fileNameAck;
    }

    return export;

}

public static AVADAIReportExportTable findAckByExecutionId(
    AVADAIServerId      _serverId,
    AVADAIExecutionId   _executionId,
    boolean             _forUpdate = false)
{
    AVADAIReportExportTable export;

    if (_serverId && _executionId)
    {
        export.selectForUpdate(_forUpdate);

        select firstonly export
            where export.ServerId ==_serverId
                && export.ExecutionId == _executionId;

    }

    return export;

}

public static AVADAIReportExportTable findPrevious(
    AVADAIServerId _serverId, 
    AVADAIReportName _reportName,
    AVADAIReportDesign _designName,
    AVADAIRefNum _refNum,
    RecId _ignoreRecId)
{
    AVADAIReportExportTable exportTable;

    select firstonly exportTable
        where exportTable.ServerId == _serverId
            && exportTable.Report == _reportName
            && exportTable.Design == _designName
            && exportTable.RefNum == _refNum
            && exportTable.ProcessStatus != AVADAIProcessStatus::Error
            && exportTable.RecId != _ignoreRecId;

    return exportTable;
}

public static void deleteRecId(RecId _recId)
{
    AVADAIReportExportTable exportTable;

    ttsbegin;

    delete_from exportTable
        where exportTable.RecId == _recId;

    ttscommit;
}

public static AVADAIReportExportTable findOrCreate(
    AVADAIReport _reportSetup,
    AVADAIExecutionId _executionId,
    boolean _forUpdate = false,
    UserConnection _userConnection = null)
{
    #OCCRetryCount
    AVADAIReportExportTable exportTable, newExportTable;

    if (!_executionId)
    {
        throw error(strFmt("@SYS89866", fieldPName(AVADAIReportExportTable, ExecutionId)));
    }

    try
    {
        exportTable = AVADAIReportExportTable::find(_executionId, _forUpdate, _userConnection);

        if (!exportTable.RecId)
        {        
            if (_userConnection)
            {
                newExportTable.setConnection(_userConnection);
            }
            newExportTable.clear();
            newExportTable.ExportId        = _executionId;
            newExportTable.ExecutionId     = _executionId;
            newExportTable.Company         = curExt();
            newExportTable.ServerId        = _reportSetup.ServerId;
            newExportTable.Report          = _reportSetup.Report;
            newExportTable.ReportType      = _reportSetup.ReportType;
            newExportTable.Design          = _reportSetup.Design;
            newExportTable.ProcessStatus   = AVADAIProcessStatus::InProgress;
            newExportTable.insert();

            exportTable.selectForUpdate(_forUpdate);
            if (_userConnection)
            {
                exportTable.setConnection(_userConnection);
            }
            select firstonly exportTable 
                where exportTable.RecId == newExportTable.RecId;
        }
    }
    catch (Exception::DuplicateKeyException)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::DuplicateKeyExceptionNotRecovered;
        }
    }

    return exportTable;
}

/// <summary>
/// Buld file name for PDF export.
/// </summary>
/// <param name = "_report">Report configuration</param>
/// <param name = "_exportId">DMS export id</param>
/// <returns>Unique file name for pdf file</returns>
public static Filename buildReportWorkFileName(AVADAIReport _report, AVADAIExecutionId _executionId)
{
    return _report.ReportFilePrefix + _executionId +'.' + _report.ReportFileExt;
}

/// <summary>
/// Buld file name for meta data export.
/// </summary>
/// <param name = "_report">Report configuration</param>
/// <param name = "_executionId">Report execution id</param>
/// <returns>Unique file name for meta data file</returns>
public static Filename buildMetadataWorkFileName(AVADAIReport _report, AVADAIExecutionId _executionId)
{
    return _report.ReportFilePrefix + _executionId + '.' + _report.MetadataFileExt;
}

/// <summary>
/// Generate new export id for entry in the table.
/// </summary>
/// <returns>New export id</returns>
public static AVADAIExportId getNewExportId()
{
    System.DateTime dateTime    = System.DateTime::get_Now();
    return dateTime.ToString('yyyMMddHHmmssffff');
}

/// <summary>
/// Determines the process status at the point when the PDF is exported.
/// </summary>
/// <returns>In progress</returns>
public static AVADAIProcessStatus getProcessStatusReportExported()
{
    return AVADAIProcessStatus::InProgress;
}

/// <summary>
/// Determines the process status at the point when the PDF is exported.
/// </summary>
/// <returns>In progress</returns>
public static AVADAIProcessStatus getProcessStatusReportPrepared()
{
    return AVADAIProcessStatus::Prepared;
}

/// <summary>
/// Determines the process status at the point when the meta data is exported.
/// </summary>
/// <returns>In progress</returns>
public static AVADAIProcessStatus getProcessStatusMetadataExported()
{
    return AVADAIProcessStatus::InProgress;
}

public void sendToMessageQueue()
{
    ttsbegin;

    AVADAIReport DAIReport = AVADAIReport::find(
        this.ServerId,
        this.Report,
        this.Design);

    if ( (DAIReport.ExportMetadata == NoYes::No || this.MetaDataExported == NoYes::Yes)
        && (DAIReport.ExportReport == NoYes::No || this.ReportExported == NoYes::Yes)
        && this.ProcessStatus != AVADAIProcessStatus::Exported 
        && DAIReport.Active == NoYes::Yes)
    {
        if (DAIReport.ExportMetadata == NoYes::Yes)
        {
            AVAMSQTransformationDefinition transformationDefinition = AVAMSQTransformationDefinition::findId(DAIReport.MetadataTransfDefId);
            if (transformationDefinition)
            {
                AVAMSQProcessingQueue::insertIntoProcessQueue
                (transformationDefinition,
                int642Str(this.RecId),
                "",
                this.MetadataFileName);
            }
        }

        if (DAIReport.ExportReport == NoYes::Yes)
        {
            AVADAIReportExportWork reportExportWork = AVADAIReportExportWork::find(this);

            if (reportExportWork)
            {
                AVAMSQProcessingQueue::insertIntoProcessQueueContainer(DAIReport.ReportTransfDefId, reportExportWork.ReportData, this.ReportFileName);//, this.ExecutionId);
            }
        }

        this.ProcessStatus = AVADAIProcessStatus::Prepared;
    }

    ttscommit;
}

public void update()
{
    //only for the first time
    if(this.ProcessStatus == AVADAIProcessStatus::InProgress)
    {
        this.sendToMessageQueue();
    }
    super();
}

/// <summary>
/// delete the temporary export table
/// </summary>
/// <param name = "_executionId"></param>
static public void deleteTempExportTable(AVADAIExecutionId _executionId)
{
    // delete PDF and protocol entry if it was created
    UserConnection userConnection = new UserConnection();
    userConnection.ttsBegin();
    AVADAIReportExportTable exportTable = AVADAIReportExportTable::find(_executionId, true, userConnection);
    if (exportTable)
    {
        exportTable.delete();
    }
    userConnection.ttsCommit();
}
